    referenceId: string
  }>
}

/**
 * Complete a repair with payment data (single or split methods).
 *
 * Atomic transaction: validates → deducts stock → creates linked sale → marks completed.
 */
export async function completeRepairPayment(
  repairId: string,
  input: CompleteRepairInput,
): Promise<CompleteRepairResult> {
  const response = await fetch(`/api/repairs/${repairId}/complete`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
