  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Payment completion failed' }))
    throw new Error(error.error || `Failed to complete repair (status ${response.status})`)
  }

  return response.json() as Promise<CompleteRepairResult>
}

